// Mock in-transit freight shipments with exceptions (fictional) - stands in for a TMS API
const shipments = [
  { shipment_id: 'SHP-5001', customer_name: 'Acme Foods (demo)', cargo: 'Refrigerated produce', cargo_value_usd: 185000, carrier: 'Demo Carrier A', exception_type: 'Reefer unit failure', exception_detail: 'Trailer temperature rose to 52F, limit is 38F. Driver stopped at a rest area.', delay_hours: 9, sla_deadline_hours: 6, location: 'Harrisburg, PA' },
  { shipment_id: 'SHP-5002', customer_name: 'Brightline Retail (demo)', cargo: 'Boxed apparel', cargo_value_usd: 42000, carrier: 'Demo Carrier B', exception_type: 'Weather delay', exception_detail: 'Snow closure on I-80, truck holding at terminal. Expected to resume tomorrow morning.', delay_hours: 14, sla_deadline_hours: 48, location: 'Toledo, OH' },
  { shipment_id: 'SHP-5003', customer_name: 'Cobalt Electronics (demo)', cargo: 'Server hardware', cargo_value_usd: 310000, carrier: 'Demo Carrier C', exception_type: 'Missed pickup appointment', exception_detail: 'Carrier arrived 3 hours after the dock window. Dock rescheduled for tomorrow.', delay_hours: 20, sla_deadline_hours: 24, location: 'Newark, NJ' },
  { shipment_id: 'SHP-5004', customer_name: 'Dune Home Goods (demo)', cargo: 'Furniture', cargo_value_usd: 9500, carrier: 'Demo Carrier D', exception_type: 'Paperwork discrepancy', exception_detail: 'BOL piece count differs by 1 carton; receiver will accept with notation.', delay_hours: 1, sla_deadline_hours: 72, location: 'Atlanta, GA' },
  { shipment_id: 'SHP-5005', customer_name: 'Everly Pharma (demo)', cargo: 'Over-the-counter medicine', cargo_value_usd: 76000, carrier: 'Demo Carrier E', exception_type: 'Late delivery', exception_detail: 'Driver running 3 hours behind due to traffic. New ETA 17:00 against a 14:00 appointment.', delay_hours: 3, sla_deadline_hours: 12, location: 'Columbus, OH' }
];
return [{ json: { fetched_at: new Date().toISOString(), shipments } }];

